    {{ stg_date('"EVENT_END_DATE"') }} as event_end_date,
    {{ stg_date('"EVENT_ACTUAL_DATE"') }} as event_actual_date,
    EVENT_COMMENTS_TEXT as event_comments_text,
    EVENT_MILESTONE_CODE as event_milestone_code,
    EVENT_REASON_CODE as event_reason_code,
    {{ stg_date('"FIRST_REPORTED_DATE"') }} as first_reported_date,
    {{ stg_date('"LAST_REPORTED_DATE"') }} as last_reported_date
